<script lang="ts">
  import {currencyAmount} from '#lib/client/finance.ts';
  import {focusTrap} from '#lib/client/focus-trap.ts';
  import {refreshAll} from '$app/navigation';
  import {command,display,recordName,request,RequestError} from '#lib/client/api.ts';
  import type {Action,AppData,Row,Field} from '#lib/client/types.ts';
  import DeliverySummary from './DeliverySummary.svelte';import FieldInput from './FieldInput.svelte';import Icon from './Icon.svelte';import Status from './Status.svelte';import BankCandidates from './BankCandidates.svelte';
  let {data,action,records,onclose,onsaved}:{data:AppData;action:Action;records:Row[];onclose:()=>void;onsaved?:(results:Row[])=>void|Promise<void>}=$props();
  let payload:Row=$state({});let reason=$state('');let confirmed=$state(false);let password=$state('');let busy=$state(false);let error=$state('');let fieldErrors:Record<string,string>=$state({});let completed=$state(0);let results:Row[]=$state([]);
  const documentaryAction=$derived(['sales.delivery.confirmed','projects.acceptance.confirmed'].includes(action.name));
  const bankChange=$derived(/bank_account\.(create|update|approve|activate)/.test(action.name));const requiresReauth=$derived(['catalog.sales_price.approve','billing.recipient_profile.approve','finance.tax_decision.approve','finance.datev.prepare','finance.datev.confirm','finance.period.lock','finance.period.unlock','system.backup.create'].includes(action.name)||bankChange||/^reports\.(cost_estimate|valuation|liquidity)\.approve$/.test(action.name)||/^workforce\..*\.approve$/.test(action.name));
  const actionFields=$derived(action.name==='finance.bank.import.stage'&&!(action.fields||[]).some(field=>field.key==='mapping')?[...(action.fields||[]),{key:'mapping',label:'CSV-Spalten zuordnen · optional',type:'textarea' as const}]:action.fields||[]);
  const fields=$derived(actionFields.filter(field=>!(field.key==='reason'&&action.requiresReason)&&!(field.key==='source_movement_id'&&action.name==='inventory.stock.move'&&payload.kind!=='return')&&!(field.key==='target_id'&&action.name==='finance.bank.transaction.confirm'&&payload.target_kind==='unallocated')).map(field=>field.key==='target_id'&&['billing.payment.allocate','finance.bank.transaction.confirm'].includes(action.name)?{...field,label:payload.target_kind==='payable'?'Verbindlichkeit':'Offene Forderung',type:'reference' as const,required:true,reference:payload.target_kind==='payable'?'payables':'receivables'}:field));
  const actionLookups=$derived.by(()=>{if(action.name!=='finance.bank.transaction.confirm')return data.lookups;const lookup={...data.lookups};const candidates=data.related?.candidates||records[0]?.candidates||[];for(const candidate of candidates){const target=candidate.target_kind==='payable'?'payables':'receivables';if(!(lookup[target]||[]).some(item=>item.id===candidate.target_id))lookup[target]=[...(lookup[target]||[]),{id:candidate.target_id,name:(candidate.document_number||'Offener Beleg')+' · '+(candidate.party_name||'Geschäftspartner')}];if(!(lookup.parties||[]).some(item=>item.id===candidate.party_id))lookup.parties=[...(lookup.parties||[]),{id:candidate.party_id,name:candidate.party_name||'Geschäftspartner'}];}return lookup;});
  async function submit(event:SubmitEvent){event.preventDefault();if(busy)return;if(action.confirmation&&!confirmed){error='Bitte bestätigen Sie die geprüfte Aktion.';return;}busy=true;error='';fieldErrors={};try{if(requiresReauth)await request('/api/v1/reauth',{password});const input={...payload};for(const field of fields)if(!field.required&&input[field.key]==='')delete input[field.key];if(input.target_kind==='unallocated')delete input.target_id;for(const field of fields)if(field.type==='datetime-local'&&input[field.key])input[field.key]=new Date(String(input[field.key])).toISOString();for(const key of ['mapping','outputs','work_pattern','datev_mapping'])if(typeof input[key]==='string'&&input[key].trim()){try{input[key]=JSON.parse(input[key]);}catch{throw new Error('Die strukturierte Eingabe ist unvollständig. Bitte prüfen Sie die ausgefüllten Zeilen.');}}for(const record of records.slice(completed)){const result=await command(action.name,record.id,{...input,...(reason?{reason}:{}),...(action.confirmation?{confirmed:true}:{})},record.version);results=[...results,result];completed+=1;}await refreshAll().catch(()=>{});const next=onsaved?.(results);onclose();await next;}catch(e){error=(completed?`${completed} von ${records.length} Datensätzen erfolgreich verarbeitet. `:'')+(e instanceof Error?e.message:'Aktion fehlgeschlagen.');if(e instanceof RequestError)fieldErrors=e.fields;if(completed||e instanceof RequestError&&e.code==='VERSION_CONFLICT')await refreshAll().catch(()=>{});}finally{busy=false;}}
</script>
<div class="modal-backdrop" role="presentation" onclick={(e)=>{if(e.target===e.currentTarget&&!busy)onclose();}}><div class="modal" role="dialog" use:focusTrap aria-modal="true" aria-labelledby="action-title" tabindex="-1" onkeydown={(e)=>{if(e.key==='Escape'&&!busy)onclose();}}><header class="modal-header"><div><h2 id="action-title">{action.label}</h2><p>Prüfen Sie den angezeigten Stand. Die Aktion wird erst nach Ihrer Bestätigung ausgeführt.</p></div><button class="icon-button" aria-label="Schließen" disabled={busy} onclick={onclose}><Icon name="close"/></button></header><form onsubmit={submit} style="display:contents"><div class="modal-body">{#if error}<div class="notice error" role="alert"><Icon name="alert"/><div>{error}</div></div>{/if}{#each records as record,index}<div class="action-preview"><h3>{recordName(record)}</h3><dl><dt>Bearbeitungsstand</dt><dd>Version {record.version??'—'}</dd>{#if record.status||record.legal_status}<dt>Status</dt><dd><Status value={record.status||record.legal_status}/></dd>{/if}{#each ['gross_total','total_gross','gross_amount','amount','service_date','due_date','customer_id','supplier_id','order_id'] as key}{#if record[key]!==undefined}<dt>{key.includes('amount')||(key==='total_gross'||key==='gross_total')?'Betrag':key==='due_date'?'Fälligkeit':key==='customer_id'?'Kunde':key==='supplier_id'?'Lieferant':'Auftrag'}</dt><dd>{key.includes('amount')||['gross_total','total_gross'].includes(key)?currencyAmount(record[key],record.currency||data.settings?.currency||'EUR'):display(record[key],key,data)}</dd>{/if}{/each}{#if index<completed}<dt>Ergebnis</dt><dd>Erfolgreich verarbeitet</dd>{/if}</dl>{#if documentaryAction}<dl class="mt"><dt>{action.name==='sales.delivery.confirmed'?'Liefertag':'Abnahmetag'}</dt><dd>{display(record.delivery_date||record.acceptance_date,'date')}</dd>{#if record.recipient}<dt>Vorgesehener Empfänger</dt><dd>{record.recipient}</dd>{/if}</dl>{#if action.name==='projects.acceptance.confirmed'}<div class="notice warning mt"><div><strong>Festgehaltene Vorbehalte / Mängel</strong><p style="white-space:pre-wrap">{record.reservations||'In diesem Entwurf sind keine Vorbehalte hinterlegt. Prüfen Sie dies vor der Bestätigung.'}</p></div></div>{/if}{/if}{#if record.terms}<p class="small mt" style="white-space:pre-wrap">{record.terms}</p>{/if}</div>{/each}{#if action.name==='sales.delivery.confirmed'&&records.length===1}<DeliverySummary rows={data.related?.lines||[]} compact/>{:else if records.length===1&&data.related?.lines?.length}<div class="table-scroll mb"><table class="data-table"><thead><tr><th>Leistung</th><th>Menge</th><th>Einheit</th><th class="number">Netto</th></tr></thead><tbody>{#each data.related.lines as line}<tr><td>{line.description}{#if line.optional}<p class="record-subtitle">Option · {line.selected?'im Umfang enthalten':'nicht ausgewählt'}</p>{/if}</td><td>{display(line.quantity,'quantity')}</td><td>{display(line.unit)}</td><td class="number">{currencyAmount(line.net_amount,records[0]?.currency||data.settings?.currency||'EUR')}</td></tr>{/each}</tbody></table></div>{/if}{#if documentaryAction}<p class="field-help mb">Tragen Sie die tatsächlich erklärende Person und ihre konkrete Erklärung ein. Ihr eigener Zugang dokumentiert den Nachweis; ein Empfang bestätigt noch keine mangelfreie Abnahme. Prüfen Sie Lieferumfang und festgehaltene Vorbehalte vor der Bestätigung.</p>{#if action.name==='projects.acceptance.confirmed'}<p class="field-help mb">Eine Frist wird nur aus einer passenden freigegebenen Vertragstypregel berechnet. Ohne diese Grundlage bleibt sie ausdrücklich unbestätigt.</p>{/if}{/if}{#if action.name==='finance.bank.transaction.confirm'&&records.length===1}<BankCandidates {data} record={records[0]} bind:payload/>{/if}{#if action.name==='purchasing.invoice.allocate'}<p class="field-help mb">Verteilen Sie höchstens den bestätigten Nettobetrag. Lagerkäufe gehören zum tatsächlich erhaltenen Bestand; direkte Fremd-, Maschinen- und Transportleistungen zum Auftrag. Eine Gutschrift wird mit negativem Betrag verrechnet. Diese Zuordnung erzeugt keine zweite Zahlung.</p>{/if}{#if action.name==='purchasing.goods.receive'}<p class="field-help mb">Wählen Sie bei mehreren gleichen Artikeln die genaue Bestellposition. Die Menge gehört zur Einheit des Bestandsartikels. Nur bei einer abweichenden Bestelleinheit ergänzen Sie den geprüften Lieferschein, die Bestellmenge und die bestätigte geometrische Umrechnungsgrundlage.</p>{/if}{#if action.name==='workforce.leave.cancel'}<p class="field-help mb">Die bestätigte Abwesenheit erhält nachvollziehbare Gegenbuchungen. Urlaub und Zeitkonto werden anhand ihrer ursprünglichen Grundlagen berichtigt.</p>{/if}{#if action.name==='finance.bank.import.stage'}<p class="field-help mb">Für CSV ordnen Sie die Spaltennamen der Bankdatei den passenden Angaben zu. Ein CAMT-Auszug enthält bereits strukturierte Angaben. Hierdurch wird noch keine Zahlung gebucht.</p>{/if}<div class="field-grid">{#each fields as field}<FieldInput {field} bind:value={payload[field.key]} lookups={actionLookups} error={fieldErrors[field.key]} prefix="action" referenceParentId={field.reference==='purchase-order-lines'?(data.module?.slug==='purchase-orders'?records[0]?.id:payload.purchase_order_id||records[0]?.purchase_order_id):undefined} referenceKind={field.key==='warranty_rule_version_id'?'warranty':undefined} referenceAsOf={field.key==='warranty_rule_version_id'?records[0]?.acceptance_date:undefined} mappingKind={action.name==='finance.bank.import.stage'?'bank':undefined}/>{/each}{#if action.requiresReason}<div class="field full"><label for="action-reason">Begründung *</label><textarea id="action-reason" bind:value={reason} required minlength={action.name.startsWith('reports.')||['workforce.leave.cancel','purchasing.invoice.allocate','catalog.sales_price.approve','catalog.sales_price.revise','billing.recipient_profile.approve','finance.tax_decision.approve'].includes(action.name)?10:5}></textarea></div>{/if}{#if requiresReauth}<div class="field full"><label for="action-password">Eigenes Passwort zur Bestätigung *</label><input id="action-password" type="password" autocomplete="current-password" bind:value={password} required/></div>{/if}</div>{#if action.confirmation}<label class="check-field mt"><input type="checkbox" bind:checked={confirmed} required/><span>Ich habe Objekt, Version und Inhalt geprüft und möchte „{action.label}“ für {records.length===1?'diesen Eintrag':`diese ${records.length} Einträge`} ausführen.</span></label>{/if}</div><footer class="modal-footer"><button type="button" class="btn" onclick={onclose} disabled={busy}>Abbrechen</button><button class="btn primary" type="submit" disabled={busy||!!(action.confirmation&&!confirmed)}>{busy?'Wird ausgeführt …':action.label}<Icon name={busy?'refresh':'arrow'} size={16} class={busy?'spin':''}/></button></footer></form></div></div>
